{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Direct PET evaluation showed [11C]prazosin and the very close analogue bunazosin have limited BBB permeability and were unsuitable for neuroimaging, indicating the prazosin scaffold does not achieve adequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The acyclic prazosin analogue [11C]GB67 also showed limited BBB permeability in the same PET study, reinforcing that the 2,4-diamino-6,7-dimethoxyquinazoline/furoylpiperazine chemotype is efflux-limited.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A dimeric prazosin analogue was detected in mouse brain at only 10-20% of blood concentrations and labeled permeable; this is weak, indirect evidence for meaningful CNS access and does not override direct prazosin PET data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct PET evidence shows prazosin and close analogues have limited BBB permeability and are unsuitable for neuroimaging; the highest-similarity dimer evidence (10-20% brain/blood) is too weak to establish meaningful CNS access. Therefore the query is predicted to fail.",
  "evidence_gaps": [
    "No quantitative unbound brain-to-plasma Kpuu for prazosin itself is provided; PET suitability may require higher brain uptake than pharmacological efficacy.",
    "Clinical use of prazosin for PTSD suggests some central alpha-1 engagement, but the provided permeability data indicate this is not robust enough to classify as meaningful CNS access.",
    "Potential active uptake or regional brain distribution is not captured by total brain/blood ratios."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

